113	
114	    public String getAddressLine2() {
115	        return this.addressLine2;
116	    }
117	
118	    public void setAddressLine2(String addressLine2) {
119	        this.addressLine2 = addressLine2;
120	    }
121	
122	    public String getAddress() {
123	        return this.address;
124	    }
125	
126	    public void setAddress(String address) {
127	        this.address = address;
128	    }
129	
130	    public String getCity() {
131	        return this.city;
132	    }
133	
134	    public void setCity(String city) {
