21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName",
28	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
29	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
30	    @Mapping(target = "initials", expression = "java(initials(owner))")
31	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
32	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
33	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
34	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
35	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
36	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
37	    @Mapping(target = "locality", expression = "java(locality(owner))")
38	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
41	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    /**
45	     * How to address the owner: their {@link Owner#getTitle() title} followed by a space
46	     * and the last name (e.g. {@code DR Franklin}), or just the last name when no title
47	     * was supplied.
48	     */
49	    default String salutation(Owner owner) {
50	        String title = owner.getTitle();
51	        return (title == null || title.isBlank())
52	            ? owner.getLastName()
53	            : title + " " + owner.getLastName();
54	    }
55	
56	    /**
57	     * The upper-cased first letters of the first and last name, dot-separated with a
58	     * trailing dot, e.g. {@code J.S.}.
59	     */
60	    default String initials(Owner owner) {
61	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
62	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
63	    }
64	
65	    /**
66	     * The owner's stored E.164 telephone number formatted for humans as the country code, a
67	     * space, then the national digits grouped in threes (e.g. {@code +61 412 345 678}). The
68	     * raw {@code telephone} field stays in E.164 form.
69	     */
70	    default String telephoneDisplay(Owner owner) {
71	        return org.springframework.samples.petclinic.rest.function.owner.Telephones
72	            .toDisplay(owner.getTelephone());
73	    }
74	
75	    /**
76	     * The Luhn check digit computed over the digits of the owner's customer code.
77	     */
78	    default int checkDigit(Owner owner) {
79	        return Luhn.checkDigit(owner.getCustomerCode());
80	    }
81	
82	    /**
83	     * The owner's membership number, formatted as {@code <customerCode>-M<YY>} where
84	     * {@code YY} is the last two digits of the fiscal year of the registration date, e.g.
85	     * {@code SMI-0007-M26}.
86	     */
87	    default String membershipNumber(Owner owner) {
88	        return MembershipNumber.of(owner);
89	    }
90	
91	    /**
92	     * The fiscal year of the owner's (business-day-adjusted) registration date, formatted as
93	     * {@code FY<YY>} (see {@link org.springframework.samples.petclinic.model.FiscalYear}).
94	     */
95	    default String fiscalYear(Owner owner) {
96	        return org.springframework.samples.petclinic.model.FiscalYear
97	            .label(owner.getRegistrationDate());
98	    }
99	
100	    /**
101	     * The owner's membership points, as defined by {@link MembershipLevel}.
102	     */
103	    default int membershipPoints(Owner owner) {
104	        return MembershipLevel.points(owner);
105	    }
106	
107	    /**
108	     * The owner's membership level from 1 to 4, as defined by {@link MembershipLevel}.
109	     */
110	    default int membershipLevel(Owner owner) {
111	        return MembershipLevel.of(owner);
112	    }
113	
114	    /**
115	     * The region the owner's customer code was minted in — its {@code <REGION>} segment
116	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.CustomerCode}).
117	     * Owners without a customer code (e.g. legacy records) fall back to deriving the region
118	     * from the postcode and city directly.
119	     */
120	    default String locality(Owner owner) {
121	        String customerCode = owner.getCustomerCode();
122	        if (customerCode == null || customerCode.isBlank()) {
123	            return CityRegion.localityOf(owner.getPostcode(), owner.getCity());
124	        }
125	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCode
126	            .region(customerCode);
127	    }
128	
129	    /**
130	     * The owner's IANA timezone, derived from their {@link #locality(Owner) locality} via
131	     * the pinned region-to-timezone table (NSW -> Australia/Sydney, VIC ->
132	     * Australia/Melbourne, QLD -> Australia/Brisbane), or {@code null} when the locality
133	     * resolves to no known region.
134	     */
135	    default String timezone(Owner owner) {
136	        return CityRegion.timezoneOf(locality(owner));
137	    }
138	
139	    /**
140	     * How the owner prefers to be contacted: {@code EMAIL} when an email address is
141	     * present, otherwise {@code PHONE}.
142	     */
143	    default String contactPreference(Owner owner) {
144	        return ContactPreference.of(owner).name();
145	    }
146	
147	    /**
148	     * The owner's age band derived from their birth date against their registration date
149	     * (see {@link AgeBand}), or {@code null} when no birth date was supplied.
150	     */
151	    default String ageBand(Owner owner) {
152	        AgeBand ageBand = AgeBand.of(owner);
153	        return ageBand == null ? null : ageBand.name();
154	    }
155	
156	    /**
157	     * The owner's derived identity key used for duplicate detection (see
158	     * {@link org.springframework.samples.petclinic.rest.function.owner.IdentityKeys}).
159	     */
160	    default String identityKey(Owner owner) {
161	        return org.springframework.samples.petclinic.rest.function.owner.IdentityKeys.of(owner);
162	    }
163	
164	    @Mapping(target = "householdMemberCount", ignore = true)
165	    Owner toOwner(OwnerDto ownerDto);
166	
167	    @Mapping(target = "id", ignore = true)
168	    @Mapping(target = "pets", ignore = true)
169	    @Mapping(target = "customerCode", ignore = true)
170	    @Mapping(target = "householdId", ignore = true)
171	    @Mapping(target = "namesakeCount", ignore = true)
172	    @Mapping(target = "householdMemberCount", ignore = true)
173	    Owner toOwner(OwnerFieldsDto ownerDto);
174	
175	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
176	
177	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
178	
179	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
180	        OwnerPageDto ownerPageDto = new OwnerPageDto();
181	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
182	        ownerPageDto.setPage(ownerPage.getNumber());
183	        ownerPageDto.setSize(ownerPage.getSize());
184	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
185	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
186	        return ownerPageDto;
187	    }
188	}
